<?php
namespace App\Http\Controllers; use App\Models\{Article,Capability,CaseStudy,Client,Industry,Page,Product,Solution,WebsiteSetting,WorkProcess}; use Illuminate\Http\Response; class SitemapController extends Controller { public function __invoke():Response{$root=rtrim(WebsiteSetting::query()->value('site_url')?:url('/'),'/');$articles=Article::publiclyVisible()->where('robots_index',true)->orderBy('slug')->get(['slug','updated_at']);$caseStudies=CaseStudy::publiclyVisible()->where('robots_index',true)->orderBy('slug')->get(['slug','updated_at']);$clients=Client::publiclyVisible()->where('robots_index',true)->orderBy('slug')->get(['slug','updated_at']);$pages=Page::publiclyVisible()->where('robots_index',true)->orderBy('slug')->get(['slug','updated_at']);$products=Product::publiclyVisible()->where('robots_index',true)->orderBy('slug')->get(['slug','updated_at']);$industries=Industry::publiclyVisible()->where('robots_index',true)->orderBy('slug')->get(['slug','updated_at']);$capabilities=Capability::publiclyVisible()->where('robots_index',true)->orderBy('slug')->get(['slug','updated_at']);$workProcesses=WorkProcess::publiclyVisible()->where('robots_index',true)->orderBy('slug')->get(['slug','updated_at']);$solutions=Solution::publiclyVisible()->where('robots_index',true)->orderBy('slug')->get(['slug','updated_at']);return response()->view('sitemap',compact('root','articles','caseStudies','clients','pages','products','solutions','industries','capabilities','workProcesses'))->header('Content-Type','application/xml');} }
